      "rationale": "Falsifies implementations that special-case attempt 0 by returning the raw base (or raw min(cap,base)) unjittered instead of passing it through rand as required by 'Attempt 0 is already jittered.'",
      "code": "import pytest
from hypothesis import given, strategies as st, settings
import impl


@given(
    base=st.floats(min_value=0.01, max_value=1000, allow_nan=False, allow_infinity=False),
    cap=st.floats(min_value=0.01, max_value=1000, allow_nan=False, allow_infinity=False),
)
@settings(max_examples=100)
def test_attempt_zero_uses_rand_of_min_cap_base(base, cap):
    rand = lambda u: u * 0.5
    result = impl.schedule(1, base, cap, rand)
    expected = min(cap, base) * 0.5
    assert result[0] == pytest.approx(expected), (
        f"schedule(1, {base}, {cap}, u*0.5) = {result}, expected [{expected}] "
        "since attempt 0 must be rand(min(cap, base)), not the unjittered base/cap"
    )
"
    }
